function showValue(kind,row,key){if(kind==='sales'&&key==='saleCode')return `<span class="sale-code-label">${esc(saleCode(row))}</span>`;if(kind==='vehicles'&&['totalCost','grossMargin','saleValue'].includes(key)){const sale=data.sales.find(s=>s.vehicleId===row.id&&s.status==='Concluída');if(key==='totalCost')return money(sale?sale.cost:costOf(row));if(key==='saleValue')return sale?money(sale.amount):'—';if(sold(row)&&!sale)return 'Acesso restrito';const value=sale?sale.amount:row.price,cost=sale?sale.cost:costOf(row),margin=value-cost;return `${money(margin)}<small>${value?(margin/value*100).toFixed(1):'0'}% · ${sale?'realizada':'prevista'}</small>`;}if(kind==='assessments'&&key==='status')return badge(({Viável:'Avaliado',Inviável:'Recusado'})[row.status]||row.status)+(row.acquiredAt?'<small>Compra confirmada</small>':'');if(kind==='assessments'&&key==='model')return esc(row.model||label('vehicles',row.vehicleId));if(kind==='sales'&&key==='model')return esc(row.model||row.leadSnapshot?.model||label('vehicles',row.vehicleId));if(kind==='sales'&&key==='modality')return esc(row.modality||'Seminova');if(key==='negotiation')return negotiationSummary(row);if(key==='situation'){const situation=leadSituation(row,serverNow());return situation?`<span class="badge ${situation==='Atrasado'?'red':situation==='Hoje'?'green':'blue'}">${situation}</span>`:'—'}if(key==='temperature')return `<span class="temperature t-${['Frio','Morno','Quente','Super quente'].indexOf(row.temperature)}">${esc(row.temperature||'Morno')}</span>`;if(key==='scheduledAt')return row.scheduledAt?new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short',timeZone:'America/Bahia'}).format(new Date(row.scheduledAt)):'Sem agendamento';const f=modules[kind].fields.find(x=>x.key===key);if(key==='status')return badge(state(kind,row));if(f?.type==='ref')return esc(label(f.ref,row[key]));if(f?.type==='date')return date(row[key]);if(key==='mileage')return Number(row.mileage||0).toLocaleString('pt-BR')+' km';if(key==='markup')return Number(row.markup||0).toLocaleString('pt-BR')+'%';if(f?.type==='number'||key==='estimatedPrice')return money(row[key]);if(key==='role')return badge(row[key]);if(key==='mileage')return Number(row.mileage||0).toLocaleString('pt-BR')+' km';if(key==='name'&&kind==='users')return `<div class="user-identity"><span class="user-photo">${avatarContent(row)}</span><strong>${esc(displayName(row))}</strong></div>`;if(key==='name')return `<strong>${esc(row[key])}</strong><small>Cadastrado em ${date(row.createdAt)}</small>`;return esc(row[key]||'—')}
