function blank(kind){const row={};for(const f of modules[kind].fields)row[f.key]=f.type==='number'?0:f.type==='date'?today():f.type==='select'?f.options[0]:f.type==='checklist'?checkNames.map(name=>({name,state:'Bom',note:'',value:0})):'';if(modules[kind].fields.some(f=>f.key==='storeId'))row.storeId=me.storeId;for(const key of ['groupId','regionId','teamId'])if(modules[kind].fields.some(f=>f.key===key))row[key]=me[key]||'';if(modules[kind].fields.some(f=>f.key==='userId'))row.userId=me.id;if(kind==='users'){row.role=roles.find(r=>roleRank(r)>roleRank(me.role))||'Vendedor';row.screens=defaultScreens(row.role).filter(x=>permissions.screens.includes(x));}if(kind==='assessments')row.markup=15;if(kind==='leads'){row.temperature='Morno';row.scheduledAt=fromLocalDateTime(minimumAppointment(serverNow()));}return row}
async function openEditor(kind,id,seed){if(kind==='sales'&&!id&&!seed){location.hash='leads';toast('Escolha o lead e clique em Registrar venda.');return;}const dependencies=[...new Set(modules[kind].fields.filter(f=>f.type==='ref'&&f.required&&!(kind==='sales'&&['leadId','storeId','userId'].includes(f.key))).map(f=>f.ref))];const missing=dependencies.find(k=>!optionsFor(k).length);if(missing){toast(`Cadastre primeiro ${modules[missing].title.toLowerCase()}.`);location.hash=missing;return}try{editing={kind,row:id?(kind==='users'?await api('users/'+id):structuredClone(find(kind,id))):{...blank(kind),...seed}};if(kind==='users'&&!Array.isArray(editing.row.screens))editing.row.screens=defaultScreens(editing.row.role).filter(k=>permissions.screens.includes(k));if(kind==='assessments'){editing.row.status=({Viável:'Avaliado',Inviável:'Recusado'})[editing.row.status]||editing.row.status;const v=find('vehicles',editing.row.vehicleId);if(v){for(const key of ['plate','year','color','category'])editing.row[key]||=v[key];editing.row.model||=v.name;}editing.row.photos||=[];}if(kind==='sales'){if(editing.row.modality==='Consórcio'){editing.row.salePlanId||=editing.row.consortium?.id||'';editing.row.consortiumInstallments||=editing.row.consortium?.months||0;editing.row.consortiumInstallment||=(editing.row.consortium?.installmentCents||0)/100;}const lead=find('leads',editing.row.leadId);editing.row.customerName||=lead?.name||editing.row.leadSnapshot?.name||'';editing.row.customerPhone||=lead?.phone||'';editing.row.customerEmail||=lead?.email||'';editing.row.documents||=[];editing.row.modality=editing.row.modality||(editing.row.vehicleId?'Seminova':'');}if(kind==='leads'&&editing.row.consortium){editing.row.administratorId=editing.row.consortium.administratorId||'honda';editing.row.catalogueFamily=editing.row.consortium.family;editing.row.catalogueModel=editing.row.consortium.model;}editStep=0;if(kind==='assessments'){assessmentDraft=null;if(location.hash!=='#avaliacoes'){location.hash='avaliacoes';}render();}else{renderEditor();$('#editor').showModal();}}catch(e){toast(e.message)}}
function inputField(f){if(editing.kind==='sales'&&editing.row.modality!=='Consórcio'&&editing.row.dossierVersion===1&&editing.row.status==='Concluída'&&['customerName','customerPhone','customerCpf','saleType','postalCode','street','streetNumber','neighborhood','state','city'].includes(f.key))f={...f,required:true};if(editing.kind==='users'&&lockedUserScope(f.key)){const row=editing.row;return `<div class="field"><label>${esc(f.label)}</label><input readonly value="${esc(label(f.ref,row[f.key]))}"><small>Vínculo definido pelo seu alcance de gestão.</small></div>`;}if(f.type==='computed')return '';if(editing.kind==='sales'&&f.key==='cost')return `<div class="field"><label>Custo do seminovo (R$)</label><input value="${money(editing.row.cost)}" readonly><small>Obtido do estoque e preservado ao registrar a venda.</small></div>`; if(editing.kind==='leads'&&editing.row.usedInterest&&['category','model','modality'].includes(f.key))return `<div class="field"><label>${esc(f.label)}</label><input readonly value="${esc(editing.row[f.key])}"></div>`;if(editing.kind==='leads'&&['category','model'].includes(f.key)){if(!editing.row.modality||editing.row.modality==='Consórcio')return '';const r=editing.row,opts=f.key==='category'?['Moto','Automóvel']:(hondaModels[r.category]||[]);return `<div class="field"><label for="f-${f.key}">${f.label} *</label><select id="f-${f.key}" name="${f.key}" required><option value="">Selecione…</option>${opts.map(v=>`<option value="${esc(v)}" ${r[f.key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`;}if(editing.kind==='sales'&&f.key==='vehicleId'&&editing.row.modality!=='Seminova'&&!editing.row.vehicleId)return '';if(editing.kind==='sales'&&['leadId','storeId','userId'].includes(f.key))return `<div class="field"><label>${f.label}</label><input value="${esc(label(f.ref,editing.row[f.key]))}" readonly></div>`;if(f.type==='administrators'){const ids=editing.row.administratorIds??['honda','disal'];return `<div class="field full"><label>Administradoras que a empresa pode negociar</label><div class="screen-options">${[['honda','Honda'],['disal','Disal']].map(([id,name])=>`<label><input type="checkbox" data-company-administrator="${id}" ${ids.includes(id)?'checked':''}> ${name}</label>`).join('')}</div><small>Esta seleção limita os planos disponíveis em novos leads.</small></div>`;}if(f.type==='plan')return editing.row.modality==='Consórcio'?planPicker(catalogue,editing.row):'';if(editing.kind==='leads'&&f.key==='interest'&&editing.row.modality==='Consórcio')return '';const r=editing.row,raw=r[f.key]??'',v=f.mask?formatInput(raw,f.mask):raw;if(f.type==='screens')return `<div class="field full"><label>Telas permitidas</label><div class="screen-options">${defaultScreens(r.role).filter(k=>permissions.screens.includes(k)).map(k=>`<label><input type="checkbox" data-screen="${k}" ${(r.screens||[]).includes(k)?'checked':''}> ${k==='painel'?'Dashboard':modules[k]?.title}</label>`).join('')}</div><small>Meu perfil está sempre disponível. O alcance dos dados continua limitado pelo cargo.</small></div>`;if(f.type==='checklist')return `<div class="checklist-fields">${r.checklist.map((c,i)=>`<div class="check-row"><strong>${c.name}</strong><select data-check="${i}" data-key="state" aria-label="Estado de ${c.name}">${['Bom','Restaurar','Trocar'].map(s=>`<option ${s===c.state?'selected':''}>${s}</option>`).join('')}</select><input data-check="${i}" data-key="note" aria-label="Observação de ${c.name}" placeholder="Intervenção necessária" value="${esc(c.note)}"><input data-check="${i}" data-key="value" aria-label="Valor de ${c.name}" type="text" inputmode="decimal" data-money value="${currencyValue(c.value)}"></div>`).join('')}</div>`;
let control;if(f.type==='datetime-local'){control=`<input id="f-${f.key}" name="${f.key}" type="datetime-local" lang="pt-BR" step="60" value="${localDateTime(v)}" ${!r.id&&!closedLead(r.status)?`min="${minimumAppointment(serverNow())}" required`:''}><small>Horário de Brasília. Novos agendamentos devem ser a partir de agora.</small>`;}else if(f.type==='ref'){const options=optionsFor(f.ref).filter(x=>!(editing.kind==='sales'&&f.key==='vehicleId')||x.id===r.vehicleId||(!sold(x)&&x.status==='Disponível'&&(!x.category||x.category===r.category))).filter(x=>f.ref==='regions'?(!r.groupId||x.groupId===r.groupId):f.ref==='stores'?(!r.regionId||x.regionId===r.regionId):['teams','users','vehicles','leads'].includes(f.ref)?(!r.storeId||x.storeId===r.storeId):true);control=`<select name="${f.key}" id="f-${f.key}" ${f.required||(editing.kind==='sales'&&f.key==='vehicleId'&&r.modality==='Seminova')?'required':''}><option value="">Selecione…</option>${options.map(x=>`<option value="${x.id}" ${v===x.id?'selected':''}>${esc(f.ref==='users'?displayName(x):x.name||x.plate)}${x.plate?' · '+esc(x.plate):''}</option>`).join('')}</select>`}else if(f.type==='select')control=`<select name="${f.key}" id="f-${f.key}" ${f.key==='modality'||f.required?'required':''}>${f.options.filter(s=>f.key!=='role'||roleRank(s)>roleRank(me.role)||me.role==='Administrador').map(s=>`<option value="${esc(s)}" ${s===v?'selected':''}>${esc(s||'Selecione…')}</option>`).join('')}</select>`;else if(f.type==='textarea')control=`<textarea name="${f.key}" id="f-${f.key}" rows="3" maxlength="4000">${esc(v)}</textarea>`;else control=`<input id="f-${f.key}" name="${f.key}" type="${f.type==='number'&&f.label.includes('(R$)')?'text':f.type}" ${f.type==='number'&&f.label.includes('(R$)')?'data-money inputmode="decimal"':''} lang="pt-BR" ${f.mask?`data-mask="${f.mask}"`:''} ${f.mask==='phone'?'inputmode="tel" autocomplete="tel-national" placeholder="(00) 00000-0000"':''} value="${esc(f.type==='number'&&f.label.includes('(R$)')?currencyValue(v):v)}" ${f.required?'required':''} ${f.type==='number'&&!f.label.includes('(R$)')?`min="${f.positive?'0.01':'0'}" max="${f.key==='installments'?999:1000000000}" step="${f.key==='installments'?1:0.01}"`:''} ${f.maxLength?`maxlength="${f.maxLength}"`:''}>`;if(f.mask==='cep')control+='<small id="cep-feedback" role="status" aria-live="polite">O endereço será consultado ao completar o CEP.</small><button type="button" class="link" data-lookup-cep>Consultar CEP</button>';return `<div class="field ${f.type==='textarea'?'full':''}"><label for="f-${f.key}">${f.label}${f.required?' *':''}</label>${control}</div>`}
function renderEditor(){const {kind,row}=editing,cfg=modules[kind];$('#editor').classList.toggle('sale-editor',kind==='sales');let fields=cfg.fields;if(kind==='assessments'){const steps=[['ownerName','ownerPhone','model','plate','category','year','color','brand','fuel','chassis','mileage','desiredValue','storeId','userId','date'],['ipva','licensing','fines','otherDebts','restrictions','checklist'],['desiredValue','purchase','fipe','fipeCode','fipeReference','transfer','settlement','markup','status','notes']];fields=cfg.fields.filter(f=>steps[editStep].includes(f.key)&&f.key!=='plate')}editorRoot().innerHTML=`<form id="edit-form"><div class="dialog-head"><div><div class="eyebrow">${row.id?'EDITAR REGISTRO':'NOVO CADASTRO'}</div><h2>${kind==='assessments'?'Avaliação do seminovo':cfg.title}</h2></div><button type="button" class="close-btn" data-action="close" aria-label="Fechar">×</button></div>${kind==='assessments'?`<div class="steps">${['Cliente e veículo','Consultas e preparação','Proposta e decisão'].map((s,i)=>`<div class="step ${i===editStep?'active':''}"><b>${i+1}</b>${s}</div>`).join('')}</div>`:''}<div class="dialog-body">${kind==='assessments'&&row.acquiredAt?'<p class="info-banner">Compra confirmada. Para alterar os custos ou a preparação, edite o seminovo no estoque.</p>':''}${kind==='users'?'<p class="info-banner">O e-mail será usado no login. A senha inicial deve ser trocada no primeiro acesso.</p>':''}${kind==='users'?userScopeHint(row):''}${kind==='sales'?`<p class="info-banner">Origem: ${esc(label('leads',row.leadId))} · ${esc(row.modality)} · ${esc(row.model||row.leadSnapshot?.model||label('vehicles',row.vehicleId))}. ${row.modality==='Consórcio'?'O valor sugerido é o crédito negociado. Confira o valor que será registrado na venda.':row.modality==='Seminova'?'Selecione o seminovo disponível. Seu custo será preservado na venda.':'Esta venda não exige veículo cadastrado em estoque.'}</p>`:''}${kind==='vehicles'?'<p class="info-banner">Este cadastro é exclusivo para seminovos.</p>':''}${kind==='assessments'&&editStep===0?plateLookupPanel():''}${kind==='sales'?(row.modality==='Consórcio'?consortiumSaleForm(fields,inputField,row,esc,catalogue.plans):saleForm(fields,inputField,row,esc)):`<div class="form-grid">${fields.map(inputField).join('')}${kind==='users'?`<div class="field full"><label for="initial-password">${row.hasAccount?'Nova senha inicial (opcional)':'Senha inicial *'}</label><input id="initial-password" name="password" type="password" value="${esc(row.password||'')}" autocomplete="new-password" minlength="8" maxlength="128" ${row.hasAccount?'':'required'}><small>Mínimo de 8 caracteres, com letra maiúscula, letra minúscula, número e caractere especial (ex.: @, #, !). Ao redefinir, a pessoa deverá trocar a senha novamente.</small></div>`:''}</div>`}${kind==='assessments'&&editStep===0?photoEditor(row.photos||[]):''}${['assessments','vehicles'].includes(kind)?'<div class="calc-summary" id="calc-summary"></div>':''}${kind==='assessments'?'<p class="form-note">O checklist compõe o orçamento de preparação. Após aceitar a proposta, use Confirmar compra para enviar o veículo ao estoque. Custos posteriores são atualizados no estoque.</p>':''}${['vehicles','assessments'].includes(kind)?'<p class="form-note">Informe a quitação separadamente apenas se não estiver incluída no valor da compra. Impostos e despesas comerciais não estão incluídos.</p>':''}<div class="form-error" role="alert" id="form-error"></div></div><div class="actions"><button type="button" class="btn secondary" data-action="${kind==='assessments'&&editStep?'previous':'close'}">${kind==='assessments'&&editStep?'← Voltar':'Cancelar'}</button><div class="save-actions">${kind==='assessments'&&editStep<2?'<button type="button" class="btn secondary" data-action="save-assessment">Salvar avaliação</button>':''}<button type="submit" class="btn" id="save">${kind==='assessments'&&editStep<2?'Continuar →':'Salvar '+(kind==='assessments'?'avaliação':cfg.singular)}</button></div></div></form>`;updateSummary();if(kind==='leads')updateAppointmentConstraint()}
function updateSummary(){if(!$('#calc-summary'))return;const r=editing.row,t=editing.kind==='assessments'?assessmentTotals(r):{cost:costOf(r),estimatedPrice:r.price};$('#calc-summary').innerHTML=`<div><small>Custo total</small><strong>${money(t.cost)}</strong></div>${editing.kind==='assessments'?`<div><small>Débitos</small><strong>${money(t.debts)}</strong></div><div><small>Preparação</small><strong>${money(t.preparation)}</strong></div>`:''}<div><small>${editing.kind==='assessments'?'Venda prevista':'Preço de venda'}</small><strong>${money(t.estimatedPrice)}</strong></div><div><small>Margem bruta prevista</small><strong>${money(t.estimatedPrice-t.cost)}</strong></div>`}
function captureInput(el){if(!editing)return;if(editing.kind==='assessments'&&el.name==='plate'&&editing.row.plate!==el.value){editing.plateResult=null;editing.plateApplied=false;if(editing.row.fipeCode){editing.row.fipe=0;editing.row.fipeCode='';editing.row.fipeReference='';}const result=$('#plate-result');if(result)result.innerHTML='';}if(el.dataset.companyAdministrator){editing.row.administratorIds=Array.from(editorRoot().querySelectorAll('[data-company-administrator]:checked')).map(x=>x.dataset.companyAdministrator);return;}if(el.dataset.screen){editing.row.screens=Array.from(editorRoot().querySelectorAll('[data-screen]:checked')).map(x=>x.dataset.screen);return}if(el.dataset.check!==undefined){editing.row.checklist[Number(el.dataset.check)][el.dataset.key]=el.dataset.key==='value'?(parseCurrency(el.value)??0):el.value}else if(el.name){const f=modules[editing.kind].fields.find(f=>f.key===el.name);editing.row[el.name]=f?.type==='number'?(f.label.includes('(R$)')?(parseCurrency(el.value)??0):Number(el.value)):f?.type==='datetime-local'?(el.value?fromLocalDateTime(el.value):''):el.value}updateSummary();if(editing.kind==='leads'){const original=editing.row.id?find('leads',editing.row.id):null;if(el.name==='scheduledAt'&&original?.scheduledAt&&editing.row.scheduledAt!==original.scheduledAt&&!closedLead(editing.row.status)){editing.row.status='Reagendado';const statusInput=$('#f-status');if(statusInput)statusInput.value='Reagendado';}updateAppointmentConstraint()}}
async function save(){if(busy||!editing)return;if(saleDocumentsBusy){toast('Aguarde o envio dos documentos.');return;}if(capturePhotosBusy){toast('Aguarde o processamento das fotos.');return;}if(!$('#edit-form').reportValidity())return;busy=true;$('#form-error').textContent='';editorRoot().querySelectorAll('button').forEach(b=>b.disabled=true);try{const {kind,row}=editing;if(kind==='sales')setSaleDocumentSending(editorRoot(),row.documents||[],true);const saved=await api(kind+(row.id?'/'+row.id:''),{method:row.id?'PUT':'POST',body:JSON.stringify(row)});const i=data[kind].findIndex(x=>x.id===saved.id);if(i>=0)data[kind][i]=saved;else data[kind].unshift(saved);$('#editor').close();editing=null;if(kind==='assessments'){assessmentDraft=null;location.hash='assessments';}render();toast(kind==='assessments'?'Avaliação salva na gestão de captações.':'Cadastro salvo.');void load({background:true,afterWrite:true})}catch(e){$('#form-error').textContent=e.message;if(editing?.kind==='sales')setSaleDocumentSending(editorRoot(),editing.row.documents||[],false,'Envio não concluído. O arquivo está preservado para tentar novamente.');}finally{busy=false;editorRoot().querySelectorAll('button').forEach(b=>b.disabled=false)}}
function confirmDelete(kind,id){const row=find(kind,id);$('#confirm').innerHTML=`<div class="dialog-head"><h2>Excluir ${modules[kind].singular}?</h2></div><div class="dialog-body"><p>O registro <strong>${esc(kind==='users'?displayName(row):row.name||label('vehicles',row.vehicleId)||modules[kind].singular)}</strong> será excluído. Registros com vínculos não podem ser removidos.</p><p class="form-error" id="delete-error" role="alert"></p></div><div class="actions"><button class="btn secondary" data-action="cancel-delete">Cancelar</button><button class="btn danger" data-action="confirm-delete" data-kind="${kind}" data-id="${id}">Excluir registro</button></div>`;$('#confirm').showModal()}
async function remove(kind,id,button){button.disabled=true;try{const row=find(kind,id);await api(`${kind}/${id}?version=${row.version}`,{method:'DELETE'});data[kind]=data[kind].filter(x=>x.id!==id);$('#confirm').close();render();toast('Registro excluído.')}catch(e){$('#delete-error').textContent=e.message}finally{button.disabled=false}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,kind,id}=b.dataset;if(action==='convert-lead'){openSale(id);return;}if(action==='situation'){filters.leads.situation=b.dataset.value;document.querySelectorAll('[data-action=situation]').forEach(x=>x.classList.toggle('selected',x.dataset.value===b.dataset.value));renderRows();return}if(action==='profile'){location.hash='perfil';return}if(action==='logout'){e.preventDefault();if(!await allowOfflineLogout())return;api('auth/logout',{method:'POST',body:'{}'}).then(()=>{me=null;assessmentDraft=null;editing=null;loaded=false;data=Object.fromEntries(Object.keys(modules).map(k=>[k,[]]));lookups={};permissions={screens:[]};boot()}).catch(e=>toast(e.message));return}if(action==='new')openEditor(kind);if(action==='edit')openEditor(kind,id);if(action==='delete')confirmDelete(kind,id);if(action==='confirm-delete')remove(kind,id,b);if(action==='cancel-delete')$('#confirm').close();if(action==='close'&&!busy){if(editing?.kind==='assessments'&&current==='avaliacoes'){assessmentDraft=null;editing=null;location.hash='assessments';}else{$('#editor').close();editing=null;}}if(action==='previous'){editStep--;renderEditor()}if(action==='save-assessment')save();if(action==='reload')load();});
