document.addEventListener('input',e=>{if(e.target.id==='structure-search'){structureFilter.q=e.target.value;renderStructurePanels();return}if(e.target.dataset.mask){const el=e.target,tail=el.value.length-(el.selectionStart??el.value.length);el.value=formatInput(el.value,el.dataset.mask);const caret=Math.max(0,el.value.length-tail);el.setSelectionRange?.(caret,caret);}if(e.target.dataset.filter){const key=e.target.dataset.filter;filters[current][key]=e.target.value;if(['region','store','team','user','status','temperature'].includes(key))render();else renderRows()}if(e.target.closest('#editor, #assessment-editor'))captureInput(e.target)});
