async function boot(){dataRefresh.invalidate();ownDashboardSales=[];resetNotifications();if(disposeChat){disposeChat();disposeChat=null;}try{const [status,accountResult]=await Promise.all([api('auth/status'),api('auth/me').then(account=>({account}),error=>({error}))]);if(status.setupRequired){showLogin(status,api,boot);return}if(accountResult.error){if(accountResult.error.status===401){showLogin(status,api,boot);return}throw accountResult.error}const account=accountResult.account;me=account.user;companyChoices=account.companies||[];recordActivity();permissions.screens=account.screens;document.body.classList.remove('locked');$('#auth-root').innerHTML='';if(me.mustChange){location.hash='perfil';render();return}await load()}catch(e){document.body.classList.add('locked');$('#auth-root').innerHTML=`<div class="auth-card"><h2>Acesso indisponível</h2><p>${esc(e.message)}</p><button class="btn" id="retry-login">Tentar novamente</button></div>`;$('#retry-login').onclick=boot}}
async function saveProfile(form){const b=Object.fromEntries(new FormData(form));b.version=me.version;if(b.newPassword!==b.confirmation){$('#profile-error').textContent='As novas senhas não conferem.';return}const button=form.querySelector('[type=submit]');if(form.dataset.photoBusy==='true')return;button.disabled=true;try{await api('profile',{method:'PUT',body:JSON.stringify(b)});toast('Perfil atualizado.');await boot()}catch(e){$('#profile-error').textContent=e.message}finally{button.disabled=false}}

