function structure(){return heading('Estrutura da operação','Cadastre e gerencie grupos, regiões, lojas e equipes nesta mesma tela.')+`<div class="filters"><input id="structure-search" aria-label="Buscar na estrutura" placeholder="Buscar grupo, região, loja ou equipe…" value="${esc(structureFilter.q)}"><select id="structure-region" aria-label="Filtrar região"><option value="">Todas as regiões</option>${optionsFor('regions').map(r=>`<option value="${r.id}" ${structureFilter.region===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div><div id="structure-panels" class="structure-panels"></div>`}
