function updateAppointmentConstraint(){const input=$('#f-scheduledAt');if(!input||!editing)return;const row=editing.row,old=row.id?find('leads',row.id):null,changed=!old||row.scheduledAt!==old.scheduledAt||closedLead(old.status)&&!closedLead(row.status)||row.status==='Reagendado'&&old.status!=='Reagendado';input.required=!closedLead(row.status);if(changed)input.min=minimumAppointment(serverNow());else input.removeAttribute('min');}

