 const stores=optionsFor('stores').filter(r=>!dash.region||r.regionId===dash.region),ids=new Set(stores.map(r=>r.id)),teams=optionsFor('teams').filter(r=>(!dash.region||ids.has(r.storeId))&&(!dash.store||r.storeId===dash.store)),users=optionsFor('users').filter(r=>(!dash.region||r.regionId===dash.region||ids.has(r.storeId))&&(!dash.store||r.storeId===dash.store)&&(!dash.team||r.teamId===dash.team));
