const rangeDialog=document.createElement('dialog');rangeDialog.className='dashboard-range-dialog';document.body.append(rangeDialog);let rangeMonth='',rangeStart='',rangeEnd='',rangePicking=false;
function renderRange(){const [year,month]=rangeMonth.split('-').map(Number),first=new Date(year,month-1,1).getDay(),days=new Date(year,month,0).getDate();rangeDialog.innerHTML=`<div class="range-head"><strong>Intervalo de datas</strong><button type="button" data-range-close aria-label="Fechar">×</button></div><div class="range-values"><input type="date" data-range-from aria-label="Data inicial" value="${rangeStart}"><span>—</span><input type="date" data-range-to aria-label="Data final" value="${rangeEnd}"></div><div class="range-month"><button data-range-month="-1" aria-label="Mês anterior">‹</button><strong>${new Date(year,month-1,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</strong><button data-range-month="1" aria-label="Próximo mês">›</button></div><div class="range-calendar">${['D','S','T','Q','Q','S','S'].map(d=>`<small>${d}</small>`).join('')}${'<span></span>'.repeat(first)}${Array.from({length:days},(_,i)=>{const date=rangeMonth+'-'+String(i+1).padStart(2,'0');return `<button data-range-day="${date}" class="${date===rangeStart||date===rangeEnd?'range-edge':date>rangeStart&&date<rangeEnd?'range-between':''}" aria-label="${date.split('-').reverse().join('/')}">${i+1}</button>`}).join('')}</div><p>${rangePicking?'Selecione a data final.':'Selecione o início e o fim do intervalo.'}</p>`;}
function applyRange(){if(!rangeStart||!rangeEnd||rangeStart>rangeEnd)return;dash={...dash,from:rangeStart,to:rangeEnd};rangeDialog.close();render()}
document.addEventListener('click',e=>{if(!e.target.closest('[data-dashboard-range]'))return;rangeStart=dash.from;rangeEnd=dash.to;rangeMonth=(rangeStart||today()).slice(0,7);rangePicking=false;renderRange();rangeDialog.showModal()});
rangeDialog.addEventListener('click',e=>{if(e.target===rangeDialog||e.target.closest('[data-range-close]')){rangeDialog.close();return}const step=e.target.closest('[data-range-month]');if(step){const [y,m]=rangeMonth.split('-').map(Number),d=new Date(y,m-1+Number(step.dataset.rangeMonth),1);rangeMonth=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');renderRange();return}const day=e.target.closest('[data-range-day]');if(!day)return;if(!rangePicking){rangeStart=day.dataset.rangeDay;rangeEnd='';rangePicking=true;renderRange()}else{rangeEnd=day.dataset.rangeDay;[rangeStart,rangeEnd]=[rangeStart,rangeEnd].sort();rangePicking=false;applyRange()}});
