document.addEventListener('click',e=>{const v=e.target.closest('[data-lead-view]');if(v){leadView=v.dataset.leadView;render();return}const d=e.target.closest('[data-calendar-day]');if(d){leadCalendar.day=d.dataset.calendarDay;renderRows();return}const step=e.target.closest('[data-calendar-step]');if(step){shiftMonth(leadCalendar,Number(step.dataset.calendarStep));renderRows();return}if(e.target.closest('[data-calendar-today]')){leadCalendar=calendarState(serverNow());renderRows();return}const priority=e.target.closest('[data-seller-situation]');if(priority){filters.leads={q:'',status:'',store:dash.store,situation:priority.dataset.sellerSituation==='hot'?'':priority.dataset.sellerSituation,temperature:priority.dataset.sellerSituation==='hot'?'hot':''};leadView='list';location.hash='leads';return}const tab=e.target.closest('[data-dashboard-view]');if(tab){dashboardView=tab.dataset.dashboardView;render();return}const metric=e.target.closest('[data-dash-detail]');if(metric){const detail=dashboardDetails[Number(metric.dataset.dashDetail)];if(!detail)return;indicatorDialog.innerHTML=`<div class="dialog-head"><div><h2 id="indicator-title">${esc(detail.title)}</h2><p class="sub">${detail.rows.length} registros no seu alcance</p></div><button class="close-btn" data-indicator-close aria-label="Fechar">×</button></div>${detail.rows.length?table(detail.kind,detail.rows,true):'<div class="empty">Nenhum registro neste indicador.</div>'}`;indicatorDialog.showModal();return}if(e.target.closest('[data-indicator-close]'))indicatorDialog.close();});
