function captureManagement(){return `<div class="capture-toolbar"><button class="btn secondary" data-capture-share>↗ Compartilhar avaliação</button><p class="sub">Receba veículos pelo seu link ou cadastre a captação aqui.</p></div><div id="capture-share-box"></div><div class="capture-statuses">${['Pendente','Avaliado','Aceito','Recusado'].map(status=>`<button data-capture-status="${status}"><span>${status}</span><strong>${data.assessments.filter(a=>(({Viável:'Avaliado',Inviável:'Recusado'})[a.status]||a.status)===status).length}</strong></button>`).join('')}</div>`;}
function stockManagement(){return `<div class="capture-statuses stock-statuses">${[['','Todos'],['Disponível','Prontos para venda'],['Em preparação','Em preparação'],['Vendido','Vendidos']].map(([status,title])=>`<button data-stock-status="${status}"><span>${title}</span><strong>${data.vehicles.filter(v=>!status||state('vehicles',v)===status).length}</strong></button>`).join('')}</div><p class="view-note">Custos incluem compra, débitos, preparação, transferência e quitação. Margem bruta = venda menos custo; antes de impostos. Para vendidos, são usados os valores registrados na venda.</p>`;}
const recordDialog=document.createElement('dialog');recordDialog.className='record-dialog';document.body.append(recordDialog);recordDialog.setAttribute('aria-labelledby','record-title');
function showRecord(kind,id){const row=find(kind,id);if(!row)return;const cfg=modules[kind];const facts=cfg.fields.filter(f=>!['screens','checklist'].includes(f.type)&&f.key!=='photo'&&f.key!=='planId'&&f.key!=='cpf').map(f=>`<div><dt>${esc(f.label)}</dt><dd>${showValue(kind,row,f.key)||'—'}</dd></div>`).join('');const totals=kind==='assessments'?assessmentTotals(row):null;recordDialog.innerHTML=`<div class="dialog-head"><div><div class="eyebrow">${cfg.title}</div><h2 id="record-title">${esc(row.name||row.model||label(kind==='sales'?'leads':'vehicles',row.leadId||row.vehicleId))}</h2></div><button class="close-btn" data-record-close aria-label="Fechar">×</button></div><div class="record-body">${row.acquiredAt?'<p class="info-banner">Compra confirmada. Este veículo já foi enviado ao estoque. Ajuste os custos e a preparação na tela de seminovos.</p>':''}<dl class="record-facts">${facts}</dl>${row.consortium?`<section class="record-plan"><h3>Plano negociado</h3>${negotiationSummary(row)}</section>`:''}${totals?`<section class="record-plan"><h3>Orçamento da captação</h3><p>Débitos: ${money(totals.debts)} · Preparação: ${money(totals.preparation)} · Custo previsto: ${money(totals.cost)}</p><div class="record-checklist">${(row.checklist||[]).map(c=>`<div><strong>${esc(c.name)}</strong><span>${esc(c.state)}</span><span>${esc(c.note)}</span><strong>${money(c.value)}</strong></div>`).join('')}</div></section>`:''}${kind==='vehicles'?`<section class="record-plan"><h3>Custos e margem</h3><dl class="record-facts">${[['totalCost','Custo total'],['saleValue','Valor vendido'],['grossMargin','Margem bruta']].map(([key,title])=>`<div><dt>${title}</dt><dd>${showValue(kind,row,key)}</dd></div>`).join('')}</dl></section>`:''}${kind==='sales'&&row.documents?.length?`<section class="record-plan"><h3>Documentos da venda</h3><div class="sale-document-grid">${row.documents.map(d=>`<div class="sale-document-download"><span>${esc(saleDocuments[d.slot]||consortiumDocuments[d.slot]||'Documento')} · ${esc(d.name)}</span><a class="document-download" href="${esc(d.url)}" download="${esc(d.name)}">Baixar documento</a></div>`).join('')}</div></section>`:''}${row.photos?.length?`<section class="record-plan"><h3>Fotos do veículo</h3><div class="record-photos">${row.photos.map((p,i)=>`<a href="${esc(p.url)}" target="_blank" rel="noopener"><img src="${esc(p.url)}" alt="Foto ${i+1} do veículo" loading="lazy"></a>`).join('')}</div></section>`:''}</div><div class="actions"><button class="btn secondary" data-record-close>Fechar</button><div class="save-actions">${kind==='assessments'&&row.capture&&!row.vehicleId&&row.status==='Aceito'&&permissions.screens.includes('vehicles')?`<button class="btn" data-buy-capture="${row.id}">Confirmar compra</button>`:''}${kind==='sales'?`<button type="button" class="btn secondary" data-print-sale="${row.id}">${navIcon('print')} Imprimir resumo</button>`:''}${kind!=='users'||row.canManage?`<button class="btn secondary" data-record-edit="${kind}" data-id="${row.id}">Editar</button>`:''}</div></div>`;recordDialog.showModal();}
function openPurchase(id){const row=find('assessments',id),totals=assessmentTotals(row);recordDialog.innerHTML=`<form id="purchase-form" data-id="${row.id}" data-version="${row.version}"><div class="dialog-head"><h2 id="record-title">Confirmar compra do seminovo</h2><button class="close-btn" type="button" data-record-close aria-label="Fechar">×</button></div><div class="record-body"><p>${esc(row.model)} · ${esc(row.plate)}</p><p>Compra: <strong>${money(row.purchase)}</strong> · Preparação: <strong>${money(totals.preparation)}</strong> · Custo total: <strong>${money(totals.cost)}</strong></p><div class="form-grid"><label>Situação inicial<select name="status"><option>Em preparação</option><option>Disponível</option></select></label><label>Preço de venda anunciado (R$)<input name="price" type="text" data-money inputmode="decimal" required value="${currencyValue(totals.estimatedPrice)}"></label></div><p class="form-note">A confirmação cria o seminovo no estoque com os valores desta avaliação e mantém o histórico da captação.</p><p class="form-error" id="purchase-error" role="alert"></p></div><div class="actions"><button class="btn secondary" type="button" data-record-close>Cancelar</button><button class="btn" type="submit">Confirmar compra e enviar ao estoque</button></div></form>`;}
document.addEventListener('click',async e=>{const view=e.target.closest('[data-view-record]');if(view){if(indicatorDialog.open)indicatorDialog.close();showRecord(view.dataset.viewRecord,view.dataset.id);return}if(e.target.closest('[data-record-close]')){recordDialog.close();return}const edit=e.target.closest('[data-record-edit]');if(edit){recordDialog.close();openEditor(edit.dataset.recordEdit,edit.dataset.id);return}const buy=e.target.closest('[data-buy-capture]');if(buy){openPurchase(buy.dataset.buyCapture);return}const status=e.target.closest('[data-capture-status],[data-stock-status]');if(status){filters[current].status=status.dataset.captureStatus??status.dataset.stockStatus;render();return}const remove=e.target.closest('[data-remove-photo]');if(remove&&editing?.kind==='assessments'&&!capturePhotosBusy){editing.row.photos.splice(Number(remove.dataset.removePhoto),1);renderEditor();return}const share=e.target.closest('[data-capture-share]');if(share){share.disabled=true;try{const {url}=await api('acquisition-link',{method:'POST'});$('#capture-share-box').innerHTML=`<div class="hc-share"><label>Seu link de captação<input id="capture-url" readonly value="${esc(url)}"></label><button class="btn" id="capture-copy">Copiar link</button><a class="btn secondary" target="_blank" rel="noopener" href="${esc(url)}">Abrir formulário ↗</a><p>As avaliações recebidas serão vinculadas a ${esc(displayName(me))}.</p></div>`;$('#capture-copy').onclick=async()=>{try{await navigator.clipboard.writeText(url);toast('Link copiado.')}catch{$('#capture-url').select();toast('Selecione e copie o link.')}}}catch(err){toast(err.message)}finally{share.disabled=false}}});
document.addEventListener('change',async e=>{if(e.target.id!=='capture-photo-files'||editing?.kind!=='assessments'||capturePhotosBusy)return;const row=editing.row;if(row.photos.length+e.target.files.length>6){$('#capture-photo-error').textContent='Anexe até 6 fotos.';return}capturePhotosBusy=true;editorRoot().querySelectorAll('button').forEach(b=>b.disabled=true);try{const ready=[];for(const file of e.target.files)ready.push(await prepareVehiclePhoto(file));row.photos.push(...ready);if(editing?.row===row)renderEditor();}catch(err){if($('#capture-photo-error'))$('#capture-photo-error').textContent=err.message;}finally{capturePhotosBusy=false;editorRoot().querySelectorAll('button').forEach(b=>b.disabled=false);}});
document.addEventListener('submit',async e=>{if(e.target.id!=='purchase-form')return;e.preventDefault();const form=e.target,button=form.querySelector('[type=submit]');button.disabled=true;try{await api('assessments/'+form.dataset.id+'/purchase',{method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(form)),price:parseCurrency(form.elements.price.value),version:Number(form.dataset.version)})});recordDialog.close();await load();toast('Compra confirmada. Seminovo cadastrado no estoque.');}catch(err){$('#purchase-error').textContent=err.message;button.disabled=false;}});

function compactLeads(rows,compact=false){const action=(row,key,title,attrs,extra='')=>`<button type="button" class="lead-icon-action ${extra}" ${attrs} data-id="${row.id}" aria-label="${title}: ${esc(row.name)}" title="${title}">${navIcon(key)}</button>`;return `<div class="table-wrap compact-lead-wrap"><table class="compact-leads"><colgroup><col class="lc-client"><col class="lc-negotiation"><col class="lc-progress"><col class="lc-agenda"><col class="lc-owner"><col class="lc-actions"></colgroup><thead><tr><th>Cliente</th><th>Negociação</th><th>Status / temperatura</th><th>Próximo contato</th><th>Responsável / loja</th><th>Ações</th></tr></thead><tbody>${rows.map(row=>{const scheduled=row.scheduledAt&&Number.isFinite(Date.parse(row.scheduledAt)),parts=scheduled?new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short',timeZone:'America/Bahia'}).format(new Date(row.scheduledAt)).split(', '):[];return `<tr><td><button class="lead-client-name" data-view-record="leads" data-id="${row.id}">${esc(row.name)}</button><small class="lead-phone">${esc(formatInput(row.phone||'','phone')||'Sem telefone')}</small></td><td><strong>${esc(row.consortium?.model||row.model||row.interest||'Modelo não informado')}</strong><small>${esc(row.modality||'Não informada')}${row.consortium?' · '+esc(row.consortium.administratorId==='honda'?'Honda':'Disal'):''}</small>${row.consortium?`<div class="lead-plan-price"><b>${row.consortium.months}× ${money(row.consortium.installmentCents/100)}</b><small>Crédito ${money(row.consortium.creditCents/100)}</small></div>`:''}</td><td><div class="lead-progress">${badge(row.status)}${showValue('leads',row,'temperature')}</div></td><td><div class="lead-appointment">${scheduled?`<time datetime="${esc(row.scheduledAt)}"><strong>${esc(parts[0])}</strong><span>${esc(parts[1]||'')}</span></time>`:'<span>Sem agendamento</span>'}${showValue('leads',row,'situation')}</div></td><td><strong>${esc(label('users',row.userId))}</strong><small>${esc(label('stores',row.storeId))}</small></td><td><div class="compact-lead-actions">${action(row,'eye','Visualizar lead','data-view-record="leads"','lead-eye')}${action(row,'edit','Editar lead','data-action="edit" data-kind="leads"')}${canSubmitLeadSale()?action(row,'sale','Registrar venda','data-action="convert-lead"','lead-sale-icon'):''}${!compact&&me.role!=='Vendedor'?action(row,'trash','Excluir lead','data-action="delete" data-kind="leads"','lead-delete-icon'):''}</div></td></tr>`}).join('')}</tbody></table></div>`;}

function lockedUserScope(key){const fixed={Administrador:[],Diretor:['groupId'],'Gerente Regional':['groupId','regionId'],'Gerente de Loja':['groupId','regionId','storeId'],Administrativo:['groupId','regionId','storeId'],Supervisor:['groupId','regionId','storeId','teamId'],Vendedor:['groupId','regionId','storeId','teamId']};return (fixed[me.role]||[]).includes(key);}
function userScopeHint(row){const scopes={Administrador:'Toda a empresa, com acesso total.',Diretor:'Todas as lojas, equipes, usuários e dados do grupo selecionado.','Gerente Regional':'Todas as lojas, equipes, usuários e dados da região selecionada.','Gerente de Loja':'Equipes, usuários e dados da loja selecionada.',Administrativo:'Gerenciamento da loja selecionada, sem acesso a leads e dashboards.',Supervisor:'Usuários e dados da equipe selecionada.',Vendedor:'Seus próprios dados e registros, sem acesso aos de outros vendedores.'};return `<div class="info-banner"><strong>Alcance de ${esc(row.role)}</strong><br>${esc(scopes[row.role]||'Selecione o cargo.')}<br><small>Os vínculos inferiores servem de referência para novos cadastros; não limitam o alcance do cargo. As telas concedidas não ampliam o alcance dos dados.</small></div>`;}

function plateLookupPanel(){return `<section class="plate-lookup"><div class="plate-lookup-head"><div><h3>Identificação e consulta FIPE</h3><p>${plateLookupEnabled?(plateLookupHomolog?'Modo de homologação ativo: a consulta retorna dados de teste, sem preencher esta captação.':'Informe a placa e consulte os dados do veículo e as versões FIPE disponíveis.'):'Aguardando configuração da chave de acesso da APIBrasil pelo administrador. O cadastro manual continua disponível.'}</p><label class="plate-input-label" for="f-plate">Placa do veículo *<input id="f-plate" name="plate" required maxlength="8" autocomplete="off" placeholder="ABC1D23" value="${esc(editing.row.plate||'')}"></label></div><button type="button" class="btn secondary" data-plate-lookup ${!plateLookupEnabled||editing.plateBusy?'disabled':''}>${editing.plateBusy?'Consultando…':'Consultar placa'}</button></div><div id="plate-result" aria-live="polite">${plateResultContent()}</div></section>`;}
function plateResultContent(){const result=editing?.plateResult;if(!result)return '';if(result.homolog)return '<p class="info-banner">Consulta em homologação concluída. Os dados retornados são de teste e não podem ser aplicados à captação. Para consultar um veículo real, o administrador deve ativar o modo de produção.</p>';if(editing.plateApplied)return '<p class="plate-feedback">Dados aplicados ao cadastro. Confira a versão, o ano e os valores antes de salvar.</p>';return `<div class="plate-result"><strong>Placa ${esc(result.plate)} · ${esc(result.provider||'Consulta FIPE')}</strong>${result.candidates.length?`<label for="plate-candidate">Confirme a versão FIPE<select id="plate-candidate"><option value="">Selecione a versão do veículo…</option>${result.candidates.map((c,i)=>`<option value="${i}">${esc(c.model)} · ${esc(c.modelYear)} · ${esc(c.fuel)} · ${money(c.value)} · ${esc(c.reference)}</option>`).join('')}</select></label>`:'<p>Não foi encontrada uma versão FIPE. Os dados do veículo podem ser aplicados e a referência FIPE preenchida manualmente.</p>'}<p class="form-note">${result.candidates.length?'Confira a versão: uma mesma placa pode retornar mais de uma correspondência. ':''}Ao aplicar, os campos retornados substituirão os dados atuais do veículo.</p><button type="button" class="btn" data-plate-apply>${result.candidates.length?'Aplicar veículo e FIPE':'Aplicar dados do veículo'}</button></div>`;}
document.addEventListener('click',async e=>{const query=e.target.closest('[data-plate-lookup]'),apply=e.target.closest('[data-plate-apply]');if((!query&&!apply)||editing?.kind!=='assessments')return;const editor=editing,row=editor.row;const plate=String(row.plate||'').toUpperCase().replace(/[^A-Z0-9]/g,'');if(query){if(editor.plateBusy)return;if(!/^[A-Z]{3}[0-9][A-Z0-9][0-9]{2}$/.test(plate)){$('#plate-result').textContent='Informe uma placa válida no campo Placa.';$('#f-plate')?.focus();return;}editor.plateBusy=true;query.disabled=true;query.textContent='Consultando…';editor.plateResult=null;editor.plateApplied=false;$('#plate-result').textContent='Buscando dados do veículo…';try{const result=await api('vehicle-lookup',{method:'POST',body:JSON.stringify({plate})});if(editing!==editor||String(row.plate||'').toUpperCase().replace(/[^A-Z0-9]/g,'')!==plate)return;editor.plateResult=result;if($('#plate-result'))$('#plate-result').innerHTML=plateResultContent();}catch(err){if(editing===editor&&$('#plate-result'))$('#plate-result').textContent=err.message;}finally{editor.plateBusy=false;const currentButton=editing===editor?document.querySelector('[data-plate-lookup]'):null;if(currentButton){currentButton.disabled=false;currentButton.textContent='Consultar placa';}}return;}const result=editor.plateResult;if(!result||result.plate!==plate||result.homolog)return;const selected=$('#plate-candidate')?.value;if(result.candidates.length&&(selected===''||selected===undefined)){toast('Selecione a versão FIPE correspondente ao veículo.');$('#plate-candidate')?.focus();return;}for(const [key,value] of Object.entries(result.vehicle))if(value)row[key]=value;const candidate=result.candidates[Number(selected)];if(candidate){row.model=[candidate.brand,candidate.model].filter(Boolean).join(' ').slice(0,150);row.fipe=candidate.value;row.fipeCode=candidate.code;row.fipeReference=candidate.reference;row.fuel=candidate.fuel||row.fuel;row.brand=candidate.brand||row.brand;if(candidate.chassis)row.chassis=candidate.chassis;if(candidate.color)row.color=candidate.color;if(candidate.category)row.category=candidate.category;if(candidate.manufacturingYear)row.year=candidate.manufacturingYear;if(candidate.modelYear)row.year=(row.year?.split('/')[0]||candidate.modelYear)+'/'+candidate.modelYear;}else{row.fipe=0;row.fipeCode='';row.fipeReference='';}editor.plateApplied=true;renderEditor();toast('Dados preenchidos. Confira antes de salvar.');});

function renderAssessmentPage(){
 $('#editor').close();$('#editor').innerHTML='';
 $('#app').innerHTML=heading('Avaliação de seminovos','Consulte a FIPE, avalie o veículo e registre sua proposta.')+`<section class="assessment-source"><label for="assessment-source">Continuar uma captação existente<select id="assessment-source"><option value="">Nova avaliação</option>${data.assessments.map(r=>`<option value="${esc(r.id)}">${esc(r.plate||'Sem placa')} · ${esc(r.model||'Veículo')} · ${esc(r.ownerName||'Cliente')} · ${esc(state('assessments',r))}</option>`).join('')}</select></label><button class="btn secondary" type="button" data-new-assessment>Nova avaliação</button><a href="#assessments">Ver captações →</a></section><section class="panel assessment-page" id="assessment-editor"></section>`;
 if(editing?.kind!=='assessments'){if(assessmentDraft){editing=assessmentDraft.editing;editStep=assessmentDraft.editStep;}else{openEditor('assessments');return;}}
 $('#assessment-source').value=editing.row.id||'';renderEditor();
}
