let saleDocumentsBusy=false;
installSaleDocumentUploads({getEditor:()=>editing,isBusy:()=>busy,onBusy:value=>saleDocumentsBusy=value,toast});
document.addEventListener('click',e=>{const button=e.target.closest('[data-remove-sale-document]');if(!button||editing?.kind!=='sales'||busy||saleDocumentsBusy)return;editing.row.documents=(editing.row.documents||[]).filter(d=>d.slot!==button.dataset.removeSaleDocument);renderEditor();});

let cepTimer,cepRequest=0;
async function fillAddressFromCep(){
 const editor=editing;if(!editor)return;const cep=String(editor.row.postalCode||'').replace(/\D/g,'');const request=++cepRequest;
 const feedback=()=>document.querySelector('#cep-feedback');
 if(cep.length!==8){if(feedback())feedback().textContent='Informe um CEP com 8 dígitos.';return;}
 const before={...editor.row};if(feedback())feedback().textContent='Consultando CEP…';
 try{const result=await api('cep?cep='+cep);if(editing!==editor||request!==cepRequest||String(editor.row.postalCode||'').replace(/\D/g,'')!==cep)return;
  const values={street:result.street,neighborhood:result.neighborhood,city:result.city,state:result.state};if(editor.kind==='stores')values.address=result.street;
  for(const [key,value] of Object.entries(values)){const input=editorRoot().querySelector('[name="'+key+'"]');if(input&&value&&editor.row[key]===before[key]){editor.row[key]=value;input.value=value;}}
  if(feedback())feedback().textContent=result.street?'Endereço encontrado. Confira os dados e informe o número.':'CEP encontrado. Complete os dados de endereço que faltarem.';
 }catch(error){if(editing===editor&&request===cepRequest&&feedback())feedback().textContent=error.message;}
}
document.addEventListener('input',e=>{if(e.target.name!=='postalCode'||!editing)return;clearTimeout(cepTimer);cepRequest++;if(String(e.target.value).replace(/\D/g,'').length===8)cepTimer=setTimeout(fillAddressFromCep,400);});
document.addEventListener('click',e=>{if(!e.target.closest('[data-lookup-cep]'))return;clearTimeout(cepTimer);fillAddressFromCep();});

let printOrigin=null,printTitle='';
function closeSalePrint(){document.querySelector('#sale-print')?.remove();document.body.classList.remove('sale-printing');document.title=printTitle||document.title;printOrigin?.focus();}
document.addEventListener('click',e=>{const button=e.target.closest('[data-print-sale]');if(button){const row=find('sales',button.dataset.printSale);if(!row||!permissions.screens.includes('sales'))return;printOrigin=button;printTitle=document.title;recordDialog.close();const area=document.createElement('section');area.id='sale-print';area.setAttribute('aria-label','Resumo da venda para impressão');area.innerHTML=salePrintContent(row,{lead:find('leads',row.leadId),store:find('stores',row.storeId),seller:find('users',row.userId)});document.querySelector('#sale-print')?.remove();document.body.append(area);document.body.classList.add('sale-printing');document.title='Venda '+saleCode(row)+' - COTAR';area.querySelector('[data-print-now]').focus();return;}if(e.target.closest('[data-print-now]'))window.print();if(e.target.closest('[data-print-close]'))closeSalePrint();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('#sale-print'))closeSalePrint();});

async function refreshChatBadge(){if(!me||me.mustChange||!loaded||!centralScreenAllowed(me,'chat')||document.hidden||chatBadgeBusy)return;chatBadgeBusy=true;const userId=me.id;try{const result=await api('chat/unread');if(me?.id!==userId)return;updateNotificationCount(result.count);if(!document.querySelector('#notification-panel')?.hidden)refreshNotificationItems();const link=document.querySelector('#navigation a[href="#chat"]');if(link){link.querySelector('.nav-chat-unread')?.remove();link.title=result.count?'Chat · '+result.count+' mensagem(ns) não lida(s)':'Chat';if(result.count){const badge=document.createElement('b');badge.className='nav-chat-unread';badge.textContent=result.count>99?'99+':String(result.count);link.append(badge);}}}catch{}finally{chatBadgeBusy=false;}}
setInterval(refreshChatBadge,12000);

function resetNotifications(){chatUnread=0;document.querySelector('#notification-panel').hidden=true;updateNotificationCount(0)}
function syncNotifications(){const bell=document.querySelector('#notification-bell');bell.hidden=!me||me.mustChange||!loaded||!centralScreenAllowed(me,'chat');if(!bell.hidden)refreshChatBadge();}
function updateNotificationCount(count){chatUnread=Number(count)||0;const badge=document.querySelector('#notification-count'),bell=document.querySelector('#notification-bell');badge.hidden=!chatUnread;badge.textContent=chatUnread>99?'99+':String(chatUnread);bell.setAttribute('aria-label',chatUnread?`${chatUnread} mensagens não lidas`:'Notificações');}
async function refreshNotificationItems(){const box=document.querySelector('#notification-items');if(document.querySelector('#notification-panel').hidden)return;try{const {threads}=await api('chat/threads');if(document.querySelector('#notification-panel').hidden)return;const unread=threads.filter(t=>Number(t.unread)>0).slice(0,6);box.innerHTML=unread.length?unread.map(t=>`<a class="notification-item" href="#chat"><span class="notification-dot"></span><span><strong>${esc(t.peer?.name||'Conversa')}</strong><small>${esc(t.body||((t.attachments||[]).length?'Enviou um anexo':'Nova mensagem'))}</small></span><b>${Number(t.unread)>99?'99+':Number(t.unread)}</b></a>`).join(''):'<p class="notification-empty">Nenhuma mensagem não lida.</p>'}catch{box.innerHTML='<p class="notification-empty">Não foi possível carregar. Tente novamente.</p>'}}
function toggleNotifications(open){const panel=document.querySelector('#notification-panel'),bell=document.querySelector('#notification-bell');open??=panel.hidden;panel.hidden=!open;bell.setAttribute('aria-expanded',String(open));if(open)refreshNotificationItems();}
document.querySelector('#notification-bell').addEventListener('click',()=>toggleNotifications());
document.querySelector('#notification-close').addEventListener('click',()=>toggleNotifications(false));
document.addEventListener('click',e=>{if(!e.target.closest('.notification-wrap'))toggleNotifications(false)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('#notification-panel').hidden){toggleNotifications(false);document.querySelector('#notification-bell').focus()}});
window.addEventListener('hashchange',()=>toggleNotifications(false));
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshChatBadge();});

document.addEventListener('click',async e=>{const button=e.target.closest('[data-chat-sale]');if(!button)return;button.disabled=true;try{const {sale}=await api('chat/sales/'+encodeURIComponent(button.dataset.chatSale));data.sales=data.sales.filter(s=>s.id!==sale.id);data.sales.push(sale);showRecord('sales',sale.id);}catch(error){toast(error.message)}finally{button.disabled=false}});

function canSubmitLeadSale(){return permissions.canSubmitSale??(permissions.screens.includes('leads')&&(me?.role==='Vendedor'||permissions.screens.includes('sales')));}

function ownSalesPanel(){const rows=ownDashboardSales.filter(inPeriod).filter(s=>!dash.store||s.storeId===dash.store).sort((a,b)=>(b.date||'').localeCompare(a.date||''));return `<section class="panel"><div class="panel-head"><div><h2>Minhas vendas · acompanhamento</h2><span class="sub">${rows.length} venda(s) no período selecionado</span></div><button class="btn secondary" data-action="reload">Atualizar status</button></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Venda / cliente</th><th>Negociação</th><th>Status</th></tr></thead><tbody>${rows.map(s=>`<tr><td><strong>${esc(s.saleCode)}</strong><small>${esc(s.customerName||label('leads',s.leadId))}</small></td><td><strong>${esc(s.model||s.modality)}</strong><small>${money(s.amount)} · ${esc((s.date||'').split('-').reverse().join('/'))}</small></td><td>${badge(s.status)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhuma venda no período selecionado.</div>'}</section>`;}

installActionMenus();

async function recordActivity(){if(!me||document.hidden)return;try{await api('activity',{method:'POST',body:'{}'})}catch{}}
setInterval(recordActivity,60000);document.addEventListener('visibilitychange',recordActivity);setTimeout(recordActivity,5000);

document.addEventListener('click',async event=>{const button=event.target.closest('[data-chart-download]');if(!button||button.disabled)return;event.preventDefault();event.stopPropagation();const panel=button.closest('.exec-panel,.analytical-panel');if(!panel)return;const parts=[`${dash.from||'Início'} a ${dash.to||'Hoje'}`];for(const [key,kind,labelName] of [['region','regions','Regional'],['store','stores','Loja'],['team','teams','Equipe'],['user','users','Vendedor']])if(dash[key])parts.push(labelName+': '+label(kind,dash[key]));for(const [key,labelName] of [['modality','Modalidade'],['status','Status'],['model','Modelo']])if(dash[key])parts.push(labelName+': '+dash[key]);button.disabled=true;button.setAttribute('aria-busy','true');try{await downloadChart(panel,{context:parts.join(' · ')});toast('Imagem baixada.');}catch(error){toast(error.message||'Não foi possível baixar a imagem. Tente novamente.');}finally{button.disabled=false;button.removeAttribute('aria-busy');}});

function renderCompanySelector(){let el=document.querySelector('#company-access-selector');if(companyChoices.length<2){el?.remove();return;}if(!el){el=document.createElement('select');el.id='company-access-selector';el.setAttribute('aria-label','Empresa em visualização');document.querySelector('.account').prepend(el);}el.innerHTML=companyChoices.map(c=>`<option value="${esc(c.id)}" ${c.id===me.companyId?'selected':''}>${esc(c.name)}${me.readOnlyCompany&&c.id!==(me.homeCompanyId||me.companyId)?' · Visualização':''}</option>`).join('');el.onchange=async()=>{selectedCompany=el.value;sessionStorage.setItem('cotar-company',selectedCompany);dataRefresh.invalidate();loaded=false;resetNotifications();await load();};el.title=me.readOnlyCompany?'Acesso de visualização à empresa selecionada':'Sua empresa';}
